/* Trill Tuner service worker.
 *
 * Makes the whole app work 100% offline after the first load: every asset is
 * precached on install, navigations fall back to the cached shell when the
 * network is gone, and anything fetched later (e.g. the APK download) is
 * runtime-cached. The asset list and cache version below are generated by
 * `node tools/build-pwa.js` — re-run it after adding or renaming files. */
const VERSION = 'tt-94bf9d44febbb672';
const ASSETS = ["/","/fonts/INTER-LICENSE.txt","/fonts/SPACE-GROTESK-LICENSE.txt","/fonts/inter-latin.woff2","/fonts/space-grotesk-latin.woff2","/icons/apple-touch-icon.png","/icons/icon-192.png","/icons/icon-512.png","/icons/icon-maskable-512.png","/js/apkshare.js","/js/app.js","/js/audio.js","/js/backing.js","/js/care.js","/js/demo.js","/js/guitar.js","/js/hookup.js","/js/jam.js","/js/learn.js","/js/lib/amps.js","/js/lib/amps2.js","/js/lib/amps3.js","/js/lib/backing.js","/js/lib/catalog-more.js","/js/lib/catalog.js","/js/lib/chords.js","/js/lib/dsp.js","/js/lib/fft.js","/js/lib/lyricsdb.js","/js/lib/notes.js","/js/lib/pedals.js","/js/lib/pedals2.js","/js/lib/pedals3.js","/js/lib/pedals4.js","/js/lib/poly.js","/js/lib/qrcode.js","/js/lib/store.js","/js/lib/sweeteners.js","/js/lib/wiring.js","/js/lib/yin.js","/js/listener.js","/js/lyrics.js","/js/metronome.js","/js/mine.js","/js/playtools.js","/js/practice.js","/js/pwa.js","/js/qr.js","/js/recorder.js","/js/remote.js","/js/rig.js","/js/settings.js","/js/share.js","/js/songsearch.js","/js/splash.js","/js/stem-worker.js","/js/stemlab.js","/js/styles.js","/js/tabmaker.js","/js/tools.js","/js/tuner.js","/js/tunings.js","/manifest.webmanifest","/neon.css","/robots.txt","/style.css","/sw.js","/index.html"];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(VERSION)
      .then(cache => cache.addAll(ASSETS))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

function cachePut(req, res) {
  if (res && (res.ok || res.type === 'opaque')) {
    caches.open(VERSION).then(cache => cache.put(req, res));
  }
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  if (req.headers.get('range')) return;         /* range requests: the server handles them (206) */
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;   /* cross-origin: straight to the network */
  if (url.pathname.indexOf('/api/') === 0) return; /* API calls are always live */

  if (req.mode === 'navigate') {
    /* network first, cached shell as the offline fallback */
    event.respondWith(
      fetch(req)
        .then(res => { cachePut(req, res.clone()); return res; })
        .catch(() => caches.match('/index.html').then(r => r || caches.match('/')))
    );
    return;
  }
  /* cache first, network fallback, then remember what the network gave us */
  event.respondWith(
    caches.match(req).then(hit => hit || fetch(req).then(res => { cachePut(req, res.clone()); return res; }))
  );
});
